<section class="p-section"><h2>Team members</h2><?php if($ctx['membership']['member_role']==='partner_owner'): ?><form class="p-form" method="post" action="<?= base_url('/partner/settings/invite') ?>"><?= csrf_field() ?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><div class="wide"><button class="tcm-btn primary">Invite Staff</button></div></form><?php endif ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Finance access</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><?= e($m['name']) ?></td><td><?= e($m['email']) ?></td><td><?= e(str_replace('partner_','',$m['member_role'])) ?></td><td><?= (int)$m['can_view_finance']?'Yes':'No' ?></td><td><?= e($m['status']) ?></td><td><?php if($ctx['membership']['member_role']==='partner_owner' && $m['user_id']!==(int)$ctx['user']['id']): ?><form method="post" action="<?= base_url('/partner/settings/members/'.$m['membership_id']) ?>"><?= csrf_field() ?><label><input type="checkbox" name="can_view_finance" value="1" <?= (int)$m['can_view_finance']?'checked':'' ?>> Finance</label><select name="status"><option value="active" <?= $m['status']==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= $m['status']==='suspended'?'selected':'' ?>>Suspended</option></select><button class="tcm-btn ghost sm">Save</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="p-section"><h2>Change password</h2><p class="p-muted">This updates the shared TCM One password for this login.</p><form class="p-form" method="post" action="<?= base_url('/partner/settings/password') ?>"><?= csrf_field() ?><label>Current password<input type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input type="password" name="new_password" minlength="10" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="new_password_confirm" minlength="10" autocomplete="new-password" required></label><div class="wide"><button class="tcm-btn secondary">Update Password</button></div></form></section>
